const raw = $input.item.json;
const body = raw.body || raw;
const accion = body.accion || (body.mensaje && !body.factura && !body.folio ? 'consultar' : 'registrar');
const sessionId = body.session_id || body.sessionId || 'sesion-web-default';
const contextoDb = body.contexto_db || { proveedores: [], facturas: [], pagos: [] };

const fRaw = body.factura || body.payloadExtra || body;
const facturaInput = {
  proveedor: (fRaw.proveedor || '').trim(),
  identificacion_fiscal: (fRaw.identificacion_fiscal || fRaw.cedula || '').trim(),
  folio: (fRaw.folio || '').trim(),
  fecha: (fRaw.fecha || '').trim(),
  subtotal: Number(fRaw.subtotal || 0),
  impuestos: Number(fRaw.impuestos || 0),
  total: Number(fRaw.total || 0),
  permitir_reprocesar: Boolean(fRaw.permitir_reprocesar || body.permitir_reprocesar)
};

let promptTexto = '';
if (accion === 'consultar') {
  promptTexto = `MODO CONSULTA DE CHAT.\nPregunta del usuario: "${body.mensaje}"\n\nDatos actuales en db.json:\n- Proveedores: ${JSON.stringify(contextoDb.proveedores)}\n- Facturas: ${JSON.stringify(contextoDb.facturas)}\n\nInstrucciones: Usa consultar_facturas o buscar_proveedor si lo necesitas y responde EXACTAMENTE a la pregunta del usuario con cifras reales. Devuelve un JSON con: { "ok": true, "data": { "mensaje": "tu respuesta detallada y específica a la pregunta", "facturas_filtradas": [/* solo las facturas relevantes a la pregunta */], "requiere_aprobacion": false, "alertas_fiscales": [] }, "error": null }`;
} else {
  promptTexto = `MODO REGISTRO Y VALIDACIÓN DE FACTURA.\nDatos extraídos del comprobante: ${JSON.stringify(facturaInput)}\nContexto db.json actual: Proveedores=${JSON.stringify(contextoDb.proveedores)}, Facturas existentes=${JSON.stringify(contextoDb.facturas.map(f => ({ id: f.id, proveedor: f.proveedor, folio: f.folio, total: f.total })))}\n\nInstrucciones: 1) Invoca validar_factura pasando el JSON de la factura. 2) Si los campos proveedor, identificacion_fiscal o folio están vacíos o total <= 0, devuelve ok: false indicando que faltan datos del comprobante. 3) Si subtotal + impuestos != total o el folio está duplicado (y permitir_reprocesar es false), devuelve ok: false con el motivo. 4) Si es válida, devuelve ok: true con el objeto factura y si requiere_aprobacion (total > 50000 o proveedor moroso/omiso).`;
}

return [{
  json: {
    accion,
    session_id: sessionId,
    mensaje: promptTexto,
    pregunta_original: body.mensaje || '',
    factura_entrada: facturaInput,
    contexto_db: contextoDb
  }
}];

let q = query;
if (q && typeof q === 'object' && q.query) q = q.query;
const criterio = (typeof q === 'string' ? q : JSON.stringify(q || '')).toLowerCase();
return JSON.stringify({ ok: true, herramienta: 'buscar_proveedor', criterio, nota: 'Usa la lista de proveedores provista en el contexto de db.json para verificar estado_fiscal (al_dia, moroso, omiso).' });

try {
  let f = query;
  if (typeof f === 'string') {
    try { f = JSON.parse(f); } catch (e) {}
  }
  if (f && typeof f === 'object' && f.query) {
    if (typeof f.query === 'string') {
      try { f = JSON.parse(f.query); } catch (e) { f = f.query; }
    } else {
      f = f.query;
    }
  }
  if (!f || typeof f !== 'object') f = {};
  const errores = [];
  if (!f.proveedor || !f.identificacion_fiscal || !f.folio) {
    errores.push('Faltan campos obligatorios (proveedor, cédula fiscal o folio).');
  }
  const sub = Number(f.subtotal || 0);
  const imp = Number(f.impuestos || 0);
  const tot = Number(f.total || 0);
  if (tot <= 0) {
    errores.push('El monto total debe ser mayor a 0.');
  }
  if (Number((sub + imp).toFixed(2)) !== Number(tot.toFixed(2))) {
    errores.push(`Error aritmético determinista: subtotal (${sub}) + impuestos (${imp}) = ${(sub + imp).toFixed(2)}, pero el total informado es ${tot}.`);
  }
  return JSON.stringify({
    ok: errores.length === 0,
    data: {
      valida: errores.length === 0,
      errores,
      requiere_aprobacion: tot > 50000
    },
    error: errores.length > 0 ? errores.join(' ') : null
  });
} catch (e) {
  return JSON.stringify({ ok: false, error: 'Error al parsear factura en validar_factura: ' + e.message });
}

const rawOutput = $input.item.json;
const entrada = $('Code Normalizar Entrada').first().json;
const outputAgente = rawOutput.output || rawOutput;
let parsedData = outputAgente;
if (typeof outputAgente === 'string') {
  const cleanJson = outputAgente.replace(/```json\n?|```/g, '').trim();
  try {
    parsedData = JSON.parse(cleanJson);
  } catch (e) {
    parsedData = {
      ok: true,
      data: {
        mensaje: outputAgente
      }
    };
  }
}

const dataFinal = parsedData.data || parsedData;
const factura = dataFinal.factura || (entrada.accion === 'registrar' ? entrada.factura_entrada : null);
const alertas = dataFinal.alertas_fiscales || [];
let requiereAprobacion = Boolean(dataFinal.requiere_aprobacion);

if (factura && Number(factura.total) > 50000) {
  requiereAprobacion = true;
}
if (alertas.length > 0) {
  requiereAprobacion = true;
}

const okStatus = parsedData.ok !== undefined ? Boolean(parsedData.ok) : !parsedData.error;

return [{
  json: {
    ok: okStatus,
    origen_ejecucion: 'n8n_agent',
    accion: entrada.accion,
    data: {
      factura: factura,
      facturas: dataFinal.facturas_filtradas || dataFinal.facturas || null,
      requiere_aprobacion: requiereAprobacion,
      alertas_fiscales: alertas,
      mensaje: dataFinal.mensaje || parsedData.mensaje || 'Procesado por el Agente Orquestador en n8n.'
    },
    error: parsedData.error || (!okStatus ? (dataFinal.mensaje || 'Rechazado en validación.') : null),
    pasos: rawOutput.intermediateSteps || []
  }
}];
